"use client";

import { loadFont as loadSerif } from "@remotion/google-fonts/InstrumentSerif";
import { loadFont } from "@remotion/google-fonts/Sora";
import type React from "react";
import { AbsoluteFill, Easing, interpolate, spring } from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import type { GradientParams } from "@/lib/remocn/gsh/gradient-engine";
import { GshGround } from "@/lib/remocn/gsh/gsh-ground";
import type { GshPresetId } from "@/lib/remocn/gsh/presets";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  DEFAULT_SETUP,
  type PovSetupElementId,
  povSetupTimeline,
  setupWordsOf,
} from "./timeline";

const { fontFamily: sora } = loadFont("normal", {
  weights: ["300", "400"],
  subsets: ["latin"],
});
const { fontFamily: serifItalic } = loadSerif("italic", {
  weights: ["400"],
  subsets: ["latin"],
});

export interface PovSetupProps {
  /** The format label. */
  label?: string;
  /** The setup line; words slide in one by one. */
  setup?: string;
  /** Lead-in of the punchline, set in the serif italic. */
  lead?: string;
  /** The key word of the punchline. */
  punch?: string;
  /** Kept for the shared draft API; the colour comes from the ground. */
  accent?: string;
  /** Text color; overrides the theme ink. */
  ink?: string;
  /** Solid fill in place of the gradient ground; "transparent" drops it. */
  background?: string;
  /** Typeface for the label, setup and punch word. Load it yourself; Sora by default. */
  fontFamily?: string;
  /** Frames between setup words. */
  stagger?: number;
  /** Frame the punchline lands. */
  punchAt?: number;
  /** Size of the copy, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  theme?: "dark" | "light";
  /** gradients.sh preset id for the ground. */
  ground?: GshPresetId;
  /** Overrides for the ground shader. */
  groundParams?: Partial<GradientParams>;
  speed?: number;
  /**
   * Moves, trims or stretches the label, its shrink, each setup word, the
   * punchline and the ground rise, by the ids in `./timeline`. Frames on
   * the scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<PovSetupElementId>;
}

const ENTER = Easing.bezier(0.32, 0.72, 0, 1);
const LIGHT = Easing.bezier(0.22, 1, 0.36, 1);
const CAMERA = Easing.bezier(0.87, 0, 0.13, 1);
const HEAVY = { mass: 1, damping: 26, stiffness: 120 };
const CARD = { mass: 0.8, damping: 18, stiffness: 160 };
const CHIP = { mass: 0.5, damping: 12, stiffness: 200 };
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const THEMES = {
  dark: {
    stage: "#0A0807",
    ink: "#F4F1EC",
    preset: "hearth" as GshPresetId,
    params: undefined as Partial<GradientParams> | undefined,
    veilFrom: 0.9,
    veilTo: 0.18,
  },
  light: {
    stage: "#F2EEE8",
    ink: "#17120E",
    preset: "paper-crease" as GshPresetId,
    params: {
      colors: ["#FF8A3A", "#FFC79A", "#F6E2CF", "#5A2410"],
      background: "#F2EEE8",
    } as Partial<GradientParams>,
    veilFrom: 0.78,
    veilTo: 0.12,
  },
} as const;

function ramp(t: number, from: number, len: number) {
  return interpolate(t, [from, from + len], [0, 1], CLAMP);
}

function kick(d: number) {
  if (d < 0) return 0;
  if (d < 2) return d / 2;
  const k = Math.max(0, 1 - (d - 2) / 8);
  return k * k;
}

function shake(d: number, amp: number, seed: number) {
  if (d < 0 || d > 8) return { x: 0, y: 0 };
  const k = (1 - d / 8) ** 2;
  return {
    x: amp * k * Math.sin(d * 2.7 + seed),
    y: amp * 0.7 * k * Math.cos(d * 3.3 + seed * 1.7),
  };
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function PovSetup(props: PovSetupProps) {
  const {
    label = "POV:",
    setup = DEFAULT_SETUP,
    lead = "and it",
    punch = "slaps.",
    ink,
    background,
    fontFamily = sora,
    scale = 1,
    delay = 0,
    theme = "dark",
    ground,
    groundParams,
    speed = 1,
    timing,
  } = props;
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    povSetupTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const labelEl = tl.get("label");
  const shrinkEl = tl.get("shrink");
  const punchEl = tl.get("punch");
  const groundEl = tl.get("ground");
  const c = THEMES[theme];
  const fg = ink ?? c.ink;
  const stage =
    background === undefined
      ? c.stage
      : background === "transparent"
        ? "transparent"
        : background;
  const tall = H > W;
  const base = tall ? W * 0.75 : H;
  const u = Math.min(W / 1280, H / 720);

  const words = setupWordsOf(setup);

  const pov = spring({ frame: t - labelEl.start, fps, config: CHIP });
  const shrink = spring({ frame: t - shrinkEl.start, fps, config: HEAVY });
  const lift = spring({
    frame: t - (punchEl.start + punchEl.beat("lift")),
    fps,
    config: HEAVY,
  });
  const p = spring({ frame: t - punchEl.start, fps, config: CARD });
  const punchOn = t >= punchEl.start;

  const camera = (at: number) => {
    const bump = Math.max(
      0.5 * kick(at - labelEl.start - labelEl.beat("kick")),
      1.2 * kick(at - punchEl.start - punchEl.beat("kick")),
    );
    const creep = interpolate(
      at,
      [shrinkEl.end, punchEl.start + punchEl.beat("creep")],
      [1, 1.035],
      {
        ...CLAMP,
        easing: CAMERA,
      },
    );
    return {
      hit: shake(at - punchEl.start - punchEl.beat("kick"), 8 * u, 2.3),
      s: creep * (1 + 0.03 * bump),
    };
  };
  const { hit, s: camScale } = camera(t);
  // Kicks, a shake and a creep add up to no clean progress, so the camera
  // counts as moving whenever it steps against either neighbouring frame.
  const camStep = (a: number, b: number) => {
    const p = camera(a);
    const q = camera(b);
    return (
      Math.abs(p.s - q.s) * W +
      Math.abs(p.hit.x - q.hit.x) +
      Math.abs(p.hit.y - q.hit.y)
    );
  };
  const camMoving =
    camStep(t + speed, t) > 1e-3 || camStep(t, t - speed) > 1e-3;

  const povScale = 1.4 - 0.4 * pov;
  const povBlur = Math.max(0, 1 - pov) * 10;
  const punchScale = 1.5 - 0.5 * p;
  const punchBlur = Math.max(0, 1 - p) * 14;
  const punchTilt = -4 * (1 - p);
  const stepBack = LIGHT(ramp(t, punchEl.start, punchEl.length));
  const setupOpacity = 1 - 0.55 * stepBack;

  const rise = LIGHT(ramp(t, groundEl.start, groundEl.length));
  const veil = c.veilFrom + (c.veilTo - c.veilFrom) * rise;
  const groundShift = (1 - rise) * 0.14 * H;

  const labelFs = 0.075 * base;
  const setupFs = (tall ? 0.105 : 0.1) * base;
  const punchFs = 0.3 * base;
  const left = (tall ? 0.08 : 0.085) * W;
  const setupWidth = W - 2 * left;

  const POV_BIG = 3.2;
  const labelGap = 0.035 * base;
  const punchGap = 0.045 * base;
  const setupLines = Math.max(
    1,
    Math.ceil((setup.length * 0.54 * setupFs) / setupWidth),
  );
  const punchLines = tall ? 2 : 1;
  const labelH = labelFs + labelGap;
  const setupH = setupLines * setupFs * 1.12;
  const punchH = punchLines * punchFs * 1.02 + punchGap;
  const top0 = (H - labelFs * POV_BIG) / 2;
  const top1 = (H - labelH - setupH) / 2;
  const top2 = (H - labelH - setupH - punchH) / 2;
  // The block is laid out where it settles and travels there by transform:
  // layout rounds a baseline moved by `top` to whole pixels.
  const blockShift = (top0 - top1) * (1 - shrink) + (top1 - top2) * (1 - lift);
  const labelScale = POV_BIG - (POV_BIG - 1) * shrink;

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      {background === undefined ? (
        <>
          <AbsoluteFill
            style={{
              top: -0.3 * H,
              height: 1.55 * H,
              transform: `translateY(${groundShift - 0.25 * H}px) scale(1.08)`,
            }}
          >
            <GshGround
              preset={ground ?? c.preset}
              params={groundParams ?? c.params}
              timeOffset={4}
              timeScale={0.45}
            />
          </AbsoluteFill>
          <AbsoluteFill
            style={{
              background: `linear-gradient(180deg, ${c.stage} 0%, ${c.stage} 38%, transparent 100%)`,
              opacity: veil,
            }}
          />
          <AbsoluteFill style={{ background: c.stage, opacity: veil * 0.55 }} />
        </>
      ) : null}

      <ScaleLayer scale={scale}>
        <div
          style={{
            position: "absolute",
            inset: 0,
            transform: `translate(${hit.x}px, ${hit.y}px) scale(${camScale})${glide(camMoving)}`,
            transformOrigin: "30% 50%",
          }}
        >
          <div
            style={{
              position: "absolute",
              left,
              right: left,
              top: top2,
              transform:
                Math.abs(blockShift) > 1e-3
                  ? `translateY(${blockShift}px)`
                  : undefined,
              display: "flex",
              flexDirection: "column",
              alignItems: "flex-start",
            }}
          >
            <div
              style={{
                fontFamily,
                fontWeight: 400,
                fontSize: labelFs,
                lineHeight: 1,
                letterSpacing: "-0.01em",
                color: fg,
                transform: `scale(${povScale * labelScale})${glide(!camMoving && Math.abs(povScale * labelScale - 1) > 1e-5)}`,
                transformOrigin: "0% 0%",
                height: labelFs,
                filter: povBlur > 0.2 ? `blur(${povBlur * u}px)` : undefined,
                opacity: ramp(
                  t,
                  labelEl.start + labelEl.beat("fadeAt"),
                  labelEl.beat("fade"),
                ),
                marginBottom: labelGap,
              }}
            >
              {label}
            </div>

            <div
              style={{
                fontFamily,
                fontWeight: 300,
                fontSize: setupFs,
                lineHeight: 1.12,
                letterSpacing: "-0.035em",
                color: fg,
                maxWidth: setupWidth,
                opacity: setupOpacity,
              }}
            >
              {words.map((w, i) => {
                const word = tl.get(`word:${i}`);
                const k = ENTER(ramp(t, word.start, word.length));
                return (
                  <span
                    key={i}
                    style={{
                      display: "inline-block",
                      overflow: "hidden",
                      verticalAlign: "top",
                      paddingBottom: "0.14em",
                      marginBottom: "-0.14em",
                      marginRight: i < words.length - 1 ? "0.24em" : 0,
                    }}
                  >
                    <span
                      style={{
                        display: "inline-block",
                        transform: `translateY(${(1 - k) * 105}%)`,
                        opacity: ramp(t, word.start, word.beat("fade")),
                      }}
                    >
                      {w}
                    </span>
                  </span>
                );
              })}
            </div>

            <div
              style={{
                height: punchLines * punchFs * 1.02,
                marginTop: punchGap,
                display: "flex",
                alignItems: "flex-end",
              }}
            >
              {punchOn ? (
                <div
                  style={{
                    display: "flex",
                    flexDirection: tall ? "column" : "row",
                    alignItems: tall ? "flex-start" : "baseline",
                    whiteSpace: "nowrap",
                    transform: `rotate(${punchTilt}deg) scale(${punchScale})`,
                    transformOrigin: "0% 70%",
                    filter:
                      punchBlur > 0.2 ? `blur(${punchBlur * u}px)` : undefined,
                    opacity: ramp(t, punchEl.start, punchEl.beat("fade")),
                    color: fg,
                  }}
                >
                  <span
                    style={{
                      fontFamily: serifItalic,
                      fontStyle: "italic",
                      fontWeight: 400,
                      fontSize: punchFs * 1.04,
                      lineHeight: 1,
                      letterSpacing: "-0.03em",
                      marginRight: "0.14em",
                    }}
                  >
                    {lead}
                  </span>
                  <span
                    style={{
                      fontFamily,
                      fontWeight: 400,
                      fontSize: punchFs,
                      lineHeight: 1,
                      letterSpacing: "-0.06em",
                      paddingRight: "0.04em",
                    }}
                  >
                    {punch}
                  </span>
                </div>
              ) : null}
            </div>
          </div>
        </div>
      </ScaleLayer>
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The "POV:" label popping in big, its shrink to a label, each setup word
// sliding up, the punchline slamming in and the ground rising behind it.
// Frames on the 30 fps scene timeline, after `delay` and `speed`. The ids
// are public: a saved `timing` prop refers to them.

export type PovSetupElementId =
  | "label"
  | "shrink"
  | `word:${number}`
  | "punch"
  | "ground";

export interface PovSetupTimingProps {
  setup?: string;
  /** Frames between setup words. */
  stagger?: number;
  /** Frame the punchline lands. */
  punchAt?: number;
}

export const DEFAULT_SETUP = "you shipped the launch video before standup";
const POV = 0;
const SHRINK = 6;
const SETUP = 10;
export const WORD_GAP = 3;
const WORD_LEN = 12;
/** A word fades in over `WORD_FADE` while it slides. */
const WORD_FADE = 4;
export const PUNCH = 54;
const RISE = 56;
const RISE_LEN = 30;

/** The setup line as words. */
export function setupWordsOf(setup: string) {
  return setup.split(/\s+/).filter(Boolean);
}

// `label` pops in (fading over `fade` from `fadeAt`, its camera kick at
// `kick`); `shrink` takes it down to a label, and the words (`word:<i>`, a
// chain) follow it. `punch` lands the punchline: the block lifts on `lift`,
// the setup steps back over its length, the camera kicks at `kick` and
// creeps until `creep`. `ground` rises behind it.
export const povSetupTimeline = defineTimeline<
  PovSetupElementId,
  PovSetupTimingProps
>(({ setup = DEFAULT_SETUP, stagger = WORD_GAP, punchAt = PUNCH }) => {
  const shift = punchAt - PUNCH;
  const punch = PUNCH + shift;
  const out: TimelineElement<PovSetupElementId>[] = [
    {
      id: "label",
      lane: "Label",
      label: "POV label",
      start: POV,
      length: SHRINK - POV,
      beats: { fadeAt: -1, fade: 2, kick: 4 },
    },
    {
      id: "shrink",
      lane: "Label",
      label: "shrink to label",
      start: SHRINK,
      length: SETUP - SHRINK,
      follows: "label",
    },
  ];
  setupWordsOf(setup).forEach((word, i) => {
    out.push({
      id: `word:${i}`,
      lane: "Setup",
      label: word,
      start: SETUP + i * stagger,
      length: WORD_LEN,
      follows: i > 0 ? `word:${i - 1}` : "shrink",
      beats: { fade: WORD_FADE },
    });
  });
  out.push(
    {
      id: "punch",
      lane: "Punch",
      label: "punchline",
      start: punch,
      length: 12,
      beats: { fade: 2, lift: 0, kick: 4, creep: 70 },
    },
    {
      id: "ground",
      lane: "Ground",
      label: "ground rise",
      start: RISE + shift,
      length: RISE_LEN,
      follows: "punch",
    },
  );
  return out.sort((a, b) => a.start - b.start);
});
